SELECT r.post_id, r.user_id, r.guild_name, r.server_name, r.last_season_grade, SUBSTRING(r.content FROM 1 FOR 200) AS content_preview, r.crt_date, r.upt_date, u.user_nm AS user_name FROM guild_recruitment r LEFT JOIN sys_user u ON r.user_id = u.user_id WHERE r.del_yn = 'N'
AND ( r.guild_name ILIKE '%' || trim(#{search}) || '%' OR r.server_name ILIKE '%' || trim(#{search}) || '%' OR r.content ILIKE '%' || trim(#{search}) || '%' )
ORDER BY r.crt_date DESC LIMIT #{limit} OFFSET #{offset}

